#!/usr/bin/env python3
"""
Child harvesting (culprits), 16 October 2026. Needs no round before it.

Adds the owner's Child Harvesting map (maps repo, child_harvesting.html) as one
row under On-planet invasion > Pre-birth frontlines > Child harvesting, read
each day from the map like the site's other maps. Made in a separate chat
while other rounds were in progress, so every change is an insertion at a
unique anchor: one already made is skipped, and if any anchor is missing the
patch stops before writing anything. Its HANDOFF note goes at the end of
HANDOFF.md, not the top.

Run from the repository root (the apply-patch workflow does).
"""
import json, pathlib, sys

EDITS = [('pipeline/sitemaps/registry.json', '   "url": "https://raw.githubusercontent.com/WelcomeToYourGalaxy/maps/main/sacrifice_map.html"\n  },\n', '  {\n   "id": "child_harvesting",\n   "name": "Baby factories, child sellers and breeders of the young, human and nonhuman, worldwide, past and present (Child Harvesting map, compiled from reporting, court and inquiry records, and the USDA)",\n   "unit": "records",\n   "colour": "#3A78A8",\n   "note": "The owner\'s Child Harvesting map (maps repo): baby factories, child sellers and breeders of the young, human and nonhuman, past and present.",\n   "url": "https://raw.githubusercontent.com/WelcomeToYourGalaxy/maps/main/child_harvesting.html"\n  },\n', 'after', '"id": "child_harvesting"'), ('map/app.js', '    { id: "site_animal_fighting", name: ', '    // Child harvesting (asked 16 October, from a separate chat): the owner\'s\n    // Child Harvesting map (maps repo), read the usual way by build_boxes.py\n    // (extract.mjs): its own boxes, and each of its parts a facet under the row.\n    { id: "child_harvesting", name: "Baby factories, child sellers and breeders of the young, human and nonhuman, worldwide, past and present (Child Harvesting map, compiled from reporting, court and inquiry records, and the USDA)", unit: "records", colour: "#3A78A8", route: "sitemap", ready: true, lazy: true,\n      dataUrl: "https://welcometoyourgalaxy.github.io/culprits-tiles-more/sitemaps/child_harvesting.places.geojson",\n      note: "The owner\'s Child Harvesting map (WelcomeToYourGalaxy/maps, child_harvesting.html), read each day from the map itself; every mark opens the map\'s own box with its sources, and where a source only alleges something the box says so. Humans: baby factories; baby-selling rings and sale points, online sales included; illegal surrogacy and egg-harvesting operations; orphanages filled with children taken from families; children killed for ritual body parts; John of God\'s alleged baby farms in Brazil (alleged by Sabrina Bittencourt in 2018, not proven in court); homes and agencies that took and sold children; baby farming, 1860s to 1920s; the Nazi Lebensborn homes and the camps where kidnapped children were Germanized; the breeding and sale of enslaved children; children taken by states and placed with other families (Russia\'s taking of Ukrainian children, Australia\'s Stolen Generations, the US Indian Adoption Project, child migrant schemes); and lines to where children were sent. Nonhumans: puppy mills and puppy farms (the Horrible Hundred reports, 2013 to 2026, and farms, raids and hubs abroad); every USDA-licensed breeder and dealer inspected since 2014, with its inspection record, placed at the middle of its postcode (the Data Liberation Project\'s copy of the USDA inspection search); Petland\'s shops and other puppy shops and brokers; foal and yearling auctions, dog auctions and online puppy sellers; puppy trade routes; breeding of other pets; lion and tiger breeding farms; breeders of dogs and monkeys sold to laboratories; mares made pregnant for hormones and blood; hatcheries where male chicks are killed at birth and those sexing eggs instead; young killed or sent away at birth (male chicks, dairy calves and goat kids, foie gras ducklings); the law on killing male chicks in each country; farm animal breeding companies; about 1,100 seed companies worldwide from company histories and national directories, and the regions where seed is multiplied; plant breeders\' rights (UPOV) by country; ornamental plant and lawn-grass breeders. Each part can be shown on its own under the row. Dots ringed rather than filled are placed at the middle of a state or country because the source names no town." },\n', 'before', '{ id: "child_harvesting", name:'), ('map/app.js', '  site_animal_sacrifice: "Where animals are sacrificed (Animal Sacrifice Map)",\n', '  child_harvesting: "Baby factories, child sellers and breeders worldwide (compiled)",\n', 'after', 'child_harvesting: "Baby factories, child sellers'), ('map/app.js', '  site_animal_sacrifice: "https://github.com/WelcomeToYourGalaxy/maps/blob/main/sacrifice_map.html",\n', '  child_harvesting: "https://github.com/WelcomeToYourGalaxy/maps/blob/main/child_harvesting.html",\n', 'after', 'child_harvesting: "https://github.com/'), ('map/app.js', '  holiday_culprits: "Read each day from the owner\'s map in the maps repo",', '  child_harvesting: "Read each day from the owner\'s map in the maps repo",\n', 'linebefore', 'child_harvesting: "Read each day'), ('map/app.js', '  { h: 2, t: "Pre-birth frontlines" },\n', '  // Child harvesting (asked 16 October): the page\'s (a) Unnecessary Harvesting,\n  // first under the pre-birth as on the page.\n  { h: 3, t: "Child harvesting" }, "child_harvesting",\n', 'after', '{ h: 3, t: "Child harvesting" }'), ('map/app.js', '    { id: "fur_world", name: ', '    // Fur trade (asked 16 October, from the child harvesting chat): the fur\n    // records that are about the trade rather than breeding the young, kept here.\n    { id: "fur_trade", name: "Fur auction houses, markets and fairs, fur sales bans, mink culls and fur-farming regions, past and present (compiled from reporting, the Fur Free Alliance and USDA)", unit: "places", colour: "#1E6FA8", route: "geojsonlive", ready: true, lazy: true,\n      files: [{ label: "Fur trade", url: "https://welcometoyourgalaxy.github.io/culprits-tiles-more/furtrade/trade.geojson" }], nameFrom: ["name"],\n      groupColours: { "Fur auctions, markets and fairs": "#0E2F66", "Fur sales and import bans": "#3FA9C2", "Mink culls": "#8C6A72", "Regional fur farming laws": "#8FD6E8", "Fur-farming regions and farm counts": "#1E6FA8" },\n      groupHint: "Coloured by kind of place",\n      note: "Compiled for this map on 16 October 2026 (moved here from the Child Harvesting map, whose subject is the young): fur auction houses, fur markets and fairs past and present (Saga Furs, Kopenhagen Fur, NAFA, Fur Harvesters, American Legend, Sojuzpushnina, the Hudson\'s Bay Company\'s London sales, Leipzig\'s Brühl, Kastoria and Siatista, Hong Kong, Shangcun, Chongfu, Haining); fur sales and import bans (California, Los Angeles, San Francisco, Berkeley, West Hollywood, Israel, India); the 2020 mink culls (Denmark, the Netherlands, Spain, Greece); regional fur farming laws (British Columbia, São Paulo); and fur-farming regions with their farm and animal counts (US mink states from USDA, Kastoria and Siatista, Hebei and Liaoning, Poland\'s provinces, Ostrobothnia). Each box gives the source; places are the town or, where no town is named, the middle of the region or country." },\n', 'before', '{ id: "fur_trade", name:'), ('map/app.js', '  fur_world: "Fur farms (Farm Transparency, Final Nail, OSM)",\n', '  fur_trade: "Fur auctions, markets, sales bans and culls (compiled)",\n', 'after', 'fur_trade: "Fur auctions, markets'), ('map/app.js', '  fur_world: ["animal", "downstream"],\n', '  fur_trade: ["animal", "upstream"],\n', 'after', 'fur_trade: ["animal"'), ('map/app.js', '  fur_world: "Copied weekly from its publisher by culprits-tiles-more",\n', '  fur_trade: "Compiled for this map from the sources in each box",\n', 'after', 'fur_trade: "Compiled for this map'), ('map/app.js', '  { h: 4, t: "Fur farms" }, "fur_world", "fur_bans",\n', '  "fur_trade",\n', 'after', '"fur_bans",\n  "fur_trade",'), ('map/test.mjs', 'console.log(`\\n${pass} passed, ${fail} failed\\n`);', 'console.log("\\nchild harvesting (16 October): the owner\'s Child Harvesting map, one row under the pre-birth");\n{\n  const src = fs.readFileSync(path.join(HERE, "app.js"), "utf8");\n  const reg = JSON.parse(fs.readFileSync(path.join(HERE, "..", "pipeline", "sitemaps", "registry.json"), "utf8")).maps;\n  const o = new Function(src.slice(src.indexOf("const PANEL_ORDER = ["), src.indexOf("function panelNodes(")) + "; return PANEL_ORDER;")();\n  const at = (t) => o.findIndex((x) => x && x.t === t);\n  const rc = at("Reproduction capture");\n  check("the map is read daily from the maps repo the usual way",\n        reg.some((m) => m.id === "child_harvesting" && !m.rich && /maps\\/main\\/child_harvesting\\.html$/.test(m.url)));\n  check("one row, its places and boxes from the copy",\n        /id: "child_harvesting"[^\\n]*route: "sitemap"/.test(src) && src.includes("sitemaps/child_harvesting.places.geojson"));\n  check("filed under Pre-birth frontlines under its own heading, before reproduction capture and genetic engineering as on the page",\n        at("Child harvesting") > at("Pre-birth frontlines") && o.indexOf("child_harvesting") === at("Child harvesting") + 1 &&\n        at("Child harvesting") < at("Genetic engineering") && (rc < 0 || at("Child harvesting") < rc) && at("Genetic engineering") < at("Invasion of the living"));\n  check("labelled, linked, short-named and marked as read daily",\n        /\\bchild_harvesting: \\["human", "downstream"\\]/.test(src) && /\\bchild_harvesting: "https:\\/\\/github\\.com\\/WelcomeToYourGalaxy\\/maps\\/blob\\/main\\/child_harvesting\\.html"/.test(src) &&\n        /\\bchild_harvesting: "Baby factories, child sellers and breeders worldwide \\(compiled\\)"/.test(src) && /\\bchild_harvesting: "Read each day/.test(src));\n  check("the fur trade records moved here from that map are a row beside the fur farms",\n        /id: "fur_trade"[^\\n]*route: "geojsonlive"/.test(src) && src.includes("furtrade/trade.geojson") &&\n        o.indexOf("fur_trade") > o.indexOf("fur_bans") && o.indexOf("fur_trade") < at("Skin farms") && /\\bfur_trade: \\["animal", "upstream"\\]/.test(src));\n}\n', 'before', 'child harvesting (16 October): the owner')]
LAYER_KIND_LINE = '  child_harvesting: ["human", "downstream"],\n'
HANDOFF = '\n\n---\n\n## Child harvesting layer (16 October, from a separate chat)\n\nNot a numbered round: made in its own chat beside the o, r and nh rounds, so it\nneeds no round before it. It inserts by anchors (each insertion skipped if it\nis already there; the patch stops, changing nothing, if an anchor is missing),\nso it applies before or after those rounds, and this note goes at the end of\nthis file rather than the top. Its map file goes into the maps repo by hand.\n\n- New map in WelcomeToYourGalaxy/maps: child_harvesting.html (Leaflet, every\n  mark a circleMarker or polygon with its popup bound when made, each part an\n  overlay in L.control.layers, so extract.mjs reads it the usual way; no\n  "rich" builder). 31 parts. Humans: baby factories, selling rings and sale\n  points, illegal surrogacy and egg farms, orphanage trafficking, ritual\n  killings, John of God\'s alleged farms, homes and agencies that sold\n  children, baby farming 1860s-1920s, Lebensborn and Germanization sites,\n  slave breeding and markets, routes. Nonhumans: puppy mills (Horrible Hundred\n  2013-2026 and farms abroad), every USDA Class A breeder and Class B dealer\n  inspected since 2014 (Data Liberation Project\'s copy of the APHIS\n  inspection search; dogs and other animals), Petland and other puppy shops\n  and brokers, puppy trade routes, other pet breeding, lion and tiger farms,\n  laboratory dog and monkey breeders, PMU and PMSG mare farms, hatcheries,\n  young killed at birth, male chick killing law, farm animal genetics, seed\n  companies (about 1,100) and seed production regions, UPOV membership,\n  ornamental and lawn-grass breeders, foal/yearling and dog auctions, state\n  taking of children, company links. Owner, 16 October: subjects mainly about\n  something else (pet cloning, fur, the flower trade, animal testing) stay\n  off; fur went to fur_trade below, flower auctions and regions to the\n  plants map (site_enslaved_plants.html, floriculture).\n- registry.json: child_harvesting (url = maps/main/child_harvesting.html), so\n  the tiles refresh\'s sitemaps job builds\n  sitemaps/child_harvesting.places.geojson and .boxes.json each full run. The\n  row draws nothing until the first refresh after the map is in the maps repo.\n- app.js: the row in SITE_MAPS (route sitemap), SHORT_NAMES, LAYER_KIND\n  (human, downstream), LAYER_SITE, NOT_LIVE; PANEL_ORDER: a "Child harvesting"\n  h3 straight after Pre-birth frontlines (the page\'s (a) Unnecessary\n  Harvesting comes before reproduction capture and engineering). The map\'s\n  overlays are the row\'s facet.\n- Second row, fur_trade (geojsonlive, furtrade/trade.geojson in\n  culprits-tiles-more, written by childharvest_tiles.py), under Animal skin\n  and fur farms > Fur farms after fur_bans: the fur records the owner moved\n  off the Child Harvesting map (16 October: fur is its own subject) -\n  auctions, markets and fairs, sales and import bans, the 2020 mink culls,\n  regional fur farming laws and fur-farming regions with counts, 45 places,\n  coloured by kind. Country fur farming bans stay with fur_bans.\n- test.mjs: one block, "child harvesting (16 October)", placed just before the\n  final pass/fail line; it checks order loosely (after Pre-birth frontlines,\n  before Reproduction capture if present and Genetic engineering) so headings\n  other chats add do not break it.\n'
HEAD = "## Child harvesting layer (16 October, from a separate chat)"


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("childharvest: run from the culprits repository root")
    texts = {}
    for f, anchor, text, where, marker in EDITS:
        s = texts.get(f) or (root / f).read_text(encoding="utf-8")
        if marker in s:
            texts[f] = s
            continue
        n = s.count(anchor)
        if n != 1:
            sys.exit(f"childharvest: in {f} the anchor {anchor[:60]!r} was found {n} times; nothing was changed")
        i = s.index(anchor)
        if where == "after":
            s = s[:i + len(anchor)] + text + s[i + len(anchor):]
        elif where == "before":
            s = s[:i] + text + s[i:]
        elif where == "linebefore":
            j = s.rfind("\n", 0, i) + 1
            s = s[:j] + text + s[j:]
        texts[f] = s
    # LAYER_KIND: after the site_animal_sacrifice line inside LAYER_KIND
    s = texts["map/app.js"]
    if LAYER_KIND_LINE not in s:
        a = s.index("const LAYER_KIND = {")
        b = s.index("\n};\n", a)
        k = s.find("\n  site_animal_sacrifice: [", a, b)
        if k < 0:
            sys.exit("childharvest: no site_animal_sacrifice line in LAYER_KIND; nothing was changed")
        e = s.index("\n", k + 1) + 1
        s = s[:e] + LAYER_KIND_LINE + s[e:]
        texts["map/app.js"] = s
    json.loads(texts["pipeline/sitemaps/registry.json"])
    for f, s in texts.items():
        (root / f).write_text(s, encoding="utf-8")
    h = root / "HANDOFF.md"
    t = h.read_text(encoding="utf-8")
    if HEAD not in t:
        h.write_text(t.rstrip("\n") + "\n" + HANDOFF, encoding="utf-8")
    print("childharvest: applied (or already there)")


if __name__ == "__main__":
    main()
